inline ::flatbuffers::Offset<SBCContribution> CreateSBCContribution(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    sbcContributorKind KIND = sbcContributorKind::Unspecified,
    ::flatbuffers::Offset<::flatbuffers::String> SENSOR_ID = 0,
    uint32_t COUNT = 0,
    double RADIAL_VARIANCE_M2 = 0.0,
    double IN_TRACK_VARIANCE_M2 = 0.0,
    double CROSS_TRACK_VARIANCE_M2 = 0.0,
    double VELOCITY_VARIANCE_M2_S2 = 0.0) {
  SBCContributionBuilder builder_(_fbb);
  builder_.add_VELOCITY_VARIANCE_M2_S2(VELOCITY_VARIANCE_M2_S2);
  builder_.add_CROSS_TRACK_VARIANCE_M2(CROSS_TRACK_VARIANCE_M2);
  builder_.add_IN_TRACK_VARIANCE_M2(IN_TRACK_VARIANCE_M2);
  builder_.add_RADIAL_VARIANCE_M2(RADIAL_VARIANCE_M2);
  builder_.add_COUNT(COUNT);
  builder_.add_SENSOR_ID(SENSOR_ID);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

