inline const SBC *GetSBC(const void *buf) {
  return ::flatbuffers::GetRoot<SBC>(buf);
}

inline const SBC *GetSizePrefixedSBC(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SBC>(buf);
}

inline const char *SBCIdentifier() {
  return "$SBC";
}

inline bool SBCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBCIdentifier());
}

inline bool SizePrefixedSBCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBCIdentifier(), true);
}

template <bool B = false>
inline bool VerifySBCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SBC>(SBCIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSBCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SBC>(SBCIdentifier());
}

inline void FinishSBCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBC> root) {
  fbb.Finish(root, SBCIdentifier());
}

inline void FinishSizePrefixedSBCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBC> root) {
  fbb.FinishSizePrefixed(root, SBCIdentifier());
}

inline std::unique_ptr<SBCT> UnPackSBC(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SBCT>(GetSBC(buf)->UnPack(res));
}

inline std::unique_ptr<SBCT> UnPackSizePrefixedSBC(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SBCT>(GetSizePrefixedSBC(buf)->UnPack(res));
}

